   230→    @Override
   231→    public AssetKey uploadAsset(IAsset asset) throws Exception {
   232→        StringBuilder sb = new StringBuilder();
   233→
   234→        // Part 1
   235→        String strMetadata = String.format("{\"public\": %s, \"retention\": \"%s\"}",
   236→                asset.isPublic(),
   237→                asset.getRetention());
   238→        sb.append("--frontier\r\n");
   239→        sb.append("Content-Type: application/json; charset=utf-8\r\n");
   240→        sb.append("Content-Length: ")
   241→                .append(strMetadata.length())
   242→                .append("\r\n\r\n");
   243→        sb.append(strMetadata)
   244→                .append("\r\n");
   245→
   246→        // Part 2
   247→        sb.append("--frontier\r\n");
   248→        sb.append("Content-Type: ")
   249→                .append(asset.getMimeType())
   250→                .append("\r\n");
   251→        sb.append("Content-Length: ")
   252→                .append(asset.getEncryptedData().length)
   253→                .append("\r\n");
   254→        sb.append("Content-MD5: ")
   255→                .append(Util.calcMd5(asset.getEncryptedData()))
   256→                .append("\r\n\r\n");
   257→
   258→        // Complete
   259→        ByteArrayOutputStream os = new ByteArrayOutputStream();
   260→        os.write(sb.toString().getBytes(StandardCharsets.UTF_8));
   261→        os.write(asset.getEncryptedData());
   262→        os.write("\r\n--frontier--\r\n".getBytes(StandardCharsets.UTF_8));
   263→
   264→        Response response = assets
   265→                .request(MediaType.APPLICATION_JSON_TYPE)
   266→                .header(HttpHeaders.AUTHORIZATION, bearer())
   267→                .post(Entity.entity(os.toByteArray(), "multipart/mixed; boundary=frontier"));
   268→
   269→        if (response.getStatus() >= 400) {
   270→            throw new HttpException(response.readEntity(String.class), response.getStatus());
   271→        }
   272→
   273→        return response.readEntity(AssetKey.class);
   274→    }
