   276→    private MultiPart getMultiPart(IAsset asset) throws NoSuchAlgorithmException {
   277→        MetaData metaData = new MetaData();
   278→        metaData.retention = asset.getRetention();
   279→        metaData.scope = asset.isPublic();
   280→
   281→        BodyPart bodyPart1 = new BodyPart(metaData, MediaType.APPLICATION_JSON_TYPE);
   282→        BodyPart bodyPart2 = new BodyPart().entity(asset.getEncryptedData());
   283→
   284→        MultivaluedMap<String, String> headers = bodyPart2.getHeaders();
   285→        headers.add("Content-Type", asset.getMimeType());
   286→        headers.add("Content-MD5", Util.calcMd5(asset.getEncryptedData()));
   287→
   288→        return new MultiPart()
   289→                .bodyPart(bodyPart1)
   290→                .bodyPart(bodyPart2);
   291→    }
